const out = [];
const free = ['gmail.com','yahoo.com','outlook.com','hotmail.com','icloud.com','aol.com','proton.me','protonmail.com','gmx.com','live.com','msn.com'];
for (const it of $input.all()) {
  const email = (it.json.email || '').toLowerCase().trim();
  const message = (it.json.message || '').trim();
  const domain = email.split('@')[1] || '';
  if (!email.includes('@') || !domain || !message) continue;
  out.push({ json: { name: it.json.name || '', email, company: it.json.company || '', role: it.json.role || '', message, domain, is_business_email: !free.includes(domain) } });
}
return out;

let company = {}; let score = {};
try { company = JSON.parse($('Extract Company').item.json.choices[0].message.content || '{}'); } catch (e) {}
try { score = JSON.parse($('Score Lead').item.json.choices[0].message.content || '{}'); } catch (e) {}
const p = $('Validate & Parse').item.json;
return { json: {
  name: p.name, email: p.email, company: p.company, role: p.role, message: p.message,
  domain: p.domain, is_business_email: p.is_business_email,
  company_industry: company.industry || null,
  company_summary: company.what_they_do || null,
  company_size_hint: company.size_hint || null,
  score: (typeof score.score === 'number') ? score.score : null,
  tier: score.tier || 'cold',
  score_reasoning: score.reasoning || '',
  suggested_action: score.suggested_action || ''
} };
